textarea{
  resize:none;
  }
 /* a{
   font-size:18px;
   text-decoration:none;
  }*/
  .triangle-down{
  width: 0; 
  height: 0; 
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;

  border-top: 8px solid #2d5ca6;
}
  .filter{
    filter: grayscale(1);
	}
  .active{
        color: #B2E0F9;
  }
  .slider-wrapper{
  	animation-name: slider-moving;
	animation-duration: 40s;
    animation-delay: 2s;
	animation-iteration-count: infinite;
  }
	.slider-wrapper:hover{
     animation-play-state: paused;
  	}
  @keyframes slider-moving {
   from{
     transform: translateX(0vw);
    }
    50%{
      transform: translateX(-82.21vw);
    }
    to{
    transform: translateX(0vw);
    }
  }
  .details-icon::before,.details-icon::after{
  content: '';
  position: absolute;
  width: 1vw;
  height: 1.5px;
  background-color: white;
}
.details-icon::before{
  transform: rotate(45deg);
  top: 0.55vw;
  left: 0.45vw;
}
.details-icon::after{
  transform: rotate(-45deg);
  top: 1.2vw;
  left: 0.45vw;
}
.second-menu{
  transition: height 0.3s ease-in;
}
.menu-block{
  transition: height 0.3s ease-in;
}
  .serch-container{
    transition: height 0.3s ease-in;
  }
  .header-trigger{
  transition: padding-top 0.3s ease-in;
}
  .listTransition{
    transform:translate3d(0vw,0px,0px) ;
  	transition: transform 0.3s ease-in;
    position: absolute;
    top: 0%;
    bottom: auto;
    left: 0%;
    right: 0%;
  }
    .initialListTransition{
    transform:translate3d(-120vw,0px,0px) ;
          position: absolute;
    top: 0%;
    bottom: auto;
    left: 0%;
    right: 0%;
  }
      .backListTransition{
    transform:translate3d(-120vw,0px,0px) ;
    transition: transform 0.3s ease-in;
            position: absolute;
    top: 0%;
    bottom: auto;
    left: 0%;
    right: 0%;
  }
    @keyframes slider-moving-tablet {
   from{
     transform: translateX(0vw);
    }
    50%{
      transform: translateX(-120vw);
    }
    to{
    transform: translateX(0vw);
    }
  }
  @keyframes slider-moving-phone {
   from{
     transform: translateX(0vw);
    }
    50%{
      transform: translateX(-190vw);
    }
    to{
    transform: translateX(0vw);
    }
  }

  @media (max-width:767px){
    .slider-wrapper{
  	animation-name: slider-moving-phone;
    }
      .details-icon::before,.details-icon::after{
  		width: 3vw;
	}
	.details-icon::before{
  		transform: rotate(45deg);
  		top: 1.6vw;
  		left: 1.4vw;
	}
	.details-icon::after{
  		transform: rotate(-45deg);
  		top: 3.5vw;
  		left: 1.4vw;
	}
  }
  @media (min-width:768px) and (max-width:1023px){
    .slider-wrapper{
  	animation-name: slider-moving-tablet;
    }
  }
