document.addEventListener('DOMContentLoaded', function() {
    const pavlyshynBlock = document.getElementById('pavlyshyn');
    const tablinksBlock = document.getElementById('cleaning');
    const tabcontentBlock = document.getElementById('tabcontent');
    const backBlock = document.getElementById('back');

    // Перевіряємо, чи існують всі необхідні елементи
    if (pavlyshynBlock && tablinksBlock && tabcontentBlock && backBlock) {

        // Обробник події для кліку на блок #pavlyshyn
        pavlyshynBlock.addEventListener('click', function() {
            if (tablinksBlock) {
                tablinksBlock.style.display = 'none';
            }
            if (tabcontentBlock) {
                tabcontentBlock.style.display = 'block';
            }
        });

        // Обробник події для кліку на блок #back
        backBlock.addEventListener('click', function() {
            if (tabcontentBlock) {
                tabcontentBlock.style.display = 'none';
            }
            if (tablinksBlock) {
                tablinksBlock.style.display = 'block';
            }
        });
    }
});
